#!/usr/bin/env python3
"""An independent reimplementation of the tex-fmt 0.5.6 command-line tool.

The behaviour implemented here was determined from the shipped documentation
and by observing the reference program's user interface.
"""

import os
import re
import sys
import threading

try:
    from generated_texts import COMPLETIONS, MAN_PAGE
except Exception:  # pragma: no cover - the packaged app always contains it
    COMPLETIONS = {}
    MAN_PAGE = ""

VERSION = "0.5.6"

# ---------------------------------------------------------------------------
# Small utilities
# ---------------------------------------------------------------------------

# The Unicode White_Space property, as used by Rust's char::is_whitespace.
_RUST_WHITESPACE = frozenset(
    "\t\n\x0b\x0c\r \u0085\u00a0\u1680"
    "\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a"
    "\u2028\u2029\u202f\u205f\u3000"
)


def is_rust_whitespace(ch):
    return ch in _RUST_WHITESPACE


def trim_start_rust(s):
    i = 0
    while i < len(s) and s[i] in _RUST_WHITESPACE:
        i += 1
    return s[i:]


def trim_end_rust(s):
    i = len(s)
    while i > 0 and s[i - 1] in _RUST_WHITESPACE:
        i -= 1
    return s[:i]


def trim_rust(s):
    return trim_end_rust(trim_start_rust(s))


def _tid():
    try:
        return threading.get_native_id()
    except Exception:
        return os.getpid()


class RustPanic(Exception):
    """Raised to reproduce a Rust panic message and exit status."""

    def __init__(self, location, message):
        super().__init__(message)
        self.location = location
        self.message = message

    def emit(self):
        text = (
            f"\nthread 'main' ({_tid()}) panicked at {self.location}:\n"
            f"{self.message}\n"
            "note: run with `RUST_BACKTRACE=1` environment variable to "
            "display a backtrace\n"
        )
        try:
            sys.stderr.write(text)
            sys.stderr.flush()
        except Exception:
            pass


def write_stdout(text):
    # Write as bytes so that surrogate-escaped file names and the input's
    # exact Unicode code points survive.
    data = text.encode("utf-8", "surrogateescape")
    try:
        sys.stdout.buffer.write(data)
        sys.stdout.buffer.flush()
    except BrokenPipeError:
        # Rust's print machinery panics on a broken pipe.  The exact
        # wording is provided by the standard library.
        raise RustPanic(
            "library/std/src/io/stdio.rs:1165:9",
            "failed printing to stdout: Broken pipe (os error 32)",
        )


_LEVEL_RANK = {"error": 1, "warn": 2, "info": 3, "debug": 4, "trace": 5}
_LEVEL_NAME = {
    "error": "ERROR",
    "warn": "WARN",
    "info": "INFO",
    "debug": "DEBUG",
    "trace": "TRACE",
}


class Logger:
    def __init__(self, verbosity="warn"):
        self.verbosity = verbosity

    def enabled(self, level):
        return _LEVEL_RANK[level] <= _LEVEL_RANK.get(self.verbosity, 2)

    def log(self, level, target, message, extra=""):
        # The reference logger has no arm for the log crate's Debug level
        # and panics if such a record is enabled (only possible at trace
        # verbosity, in practice from the recursive directory walker).
        if level == "debug" and self.enabled("debug"):
            raise RustPanic("src/logging.rs:93:18", "explicit panic")
        if not self.enabled(level):
            return
        text = f"{_LEVEL_NAME[level]}: tex-fmt {target}: {message} {extra}\n"
        try:
            sys.stderr.buffer.write(text.encode("utf-8", "surrogateescape"))
            sys.stderr.buffer.flush()
        except Exception:
            pass

    def error(self, target, message, extra=""):
        self.log("error", target, message, extra)

    def warn(self, target, message, extra=""):
        self.log("warn", target, message, extra)

    def info(self, target, message, extra=""):
        self.log("info", target, message, extra)

    def trace(self, target, message, extra=""):
        self.log("trace", target, message, extra)

    def debug_from_walker(self):
        self.log("debug", "", "")


# A logger used before the effective verbosity is known.  All user-visible
# logging after argument construction re-points this at the real logger.
LOGGER = Logger()


def line_log_extra(text):
    """The text of a line as it appears after a log message."""

    return trim_start_rust(text)


# ---------------------------------------------------------------------------
# Command-line parsing (a small, clap-compatible-enough parser)
# ---------------------------------------------------------------------------


def program_name(argv0=None):
    if argv0 is None:
        argv0 = sys.argv[0] if sys.argv else "tex-fmt"
    # clap displays the file name component of argv[0].
    name = os.path.basename(argv0.rstrip("/")) if argv0 else ""
    return name or "tex-fmt"


def help_text(prog):
    return f"""tex-fmt {VERSION}

LaTeX formatter written in Rust

Usage: {prog} [OPTIONS] [files]...

Arguments:
  [files]...  List of files to be formatted

Options:
  -c, --check               Check formatting, do not modify files
  -p, --print               Print to stdout, do not modify files
  -f, --fail-on-change      Format files and return non-zero exit code if files are modified
  -n, --nowrap              Do not wrap long lines
  -l, --wraplen <N>         Line length for wrapping [default: 80]
  -t, --tabsize <N>         Number of characters to use as tab size [default: 2]
      --usetabs             Use tabs instead of spaces for indentation
  -s, --stdin               Process stdin as a single file, output to stdout
      --config <PATH>       Path to config file
      --noconfig            Do not read any config file
  -v, --verbose             Show info messages
  -q, --quiet               Hide warning messages
      --trace               Show trace messages
      --completion <SHELL>  Generate shell completion script [possible values: bash, elvish, fish, powershell, zsh]
      --man                 Generate man page
      --args                Print arguments passed to tex-fmt and exit
  -r, --recursive           Recursively search for files to format
  -h, --help                Print help
  -V, --version             Print version
"""


# Each option: canonical key, long name, short (or None), takes a value,
# value placeholder for messages and usage strings.
OPTIONS = [
    ("check", "check", "c", False, None),
    ("print", "print", "p", False, None),
    ("fail_on_change", "fail-on-change", "f", False, None),
    ("nowrap", "nowrap", "n", False, None),
    ("wraplen", "wraplen", "l", True, "<N>"),
    ("tabsize", "tabsize", "t", True, "<N>"),
    ("usetabs", "usetabs", None, False, None),
    ("stdin", "stdin", "s", False, None),
    ("config", "config", None, True, "<PATH>"),
    ("noconfig", "noconfig", None, False, None),
    ("verbose", "verbose", "v", False, None),
    ("quiet", "quiet", "q", False, None),
    ("trace", "trace", None, False, None),
    ("completion", "completion", None, True, "<SHELL>"),
    ("man", "man", None, False, None),
    ("args", "args", None, False, None),
    ("recursive", "recursive", "r", False, None),
    ("help", "help", "h", False, None),
    ("version", "version", "V", False, None),
]
_LONG = {opt[1]: opt for opt in OPTIONS}
_SHORT = {opt[2]: opt for opt in OPTIONS if opt[2]}
SHELLS = ["bash", "elvish", "fish", "powershell", "zsh"]


class CliExit(Exception):
    def __init__(self, status, stdout="", stderr=""):
        super().__init__(stderr or stdout)
        self.status = status
        self.stdout = stdout
        self.stderr = stderr


def _clap_error(message, usage=None, prog="executable"):
    err = f"error: {message}\n"
    if usage:
        err += f"\nUsage: {usage}\n"
    err += "\nFor more information, try '--help'.\n"
    return CliExit(2, stderr=err)


def _usage_general(prog):
    return f"{prog} [OPTIONS] [files]..."


def _usage_for_option(prog, opt):
    if opt[3]:
        return f"{prog} --{opt[1]} {opt[4]} [files]..."
    return f"{prog} --{opt[1]} [files]..."


def _jaro(a, b):
    """The Jaro similarity used by clap's strsim suggestions."""

    if a == b:
        return 1.0
    la, lb = len(a), len(b)
    if la == 0 or lb == 0:
        return 0.0
    match_distance = max(la, lb) // 2 - 1
    if match_distance < 0:
        match_distance = 0
    a_matches = [False] * la
    b_matches = [False] * lb
    matches = 0
    for i, ca in enumerate(a):
        start = max(0, i - match_distance)
        end = min(i + match_distance + 1, lb)
        for j in range(start, end):
            if not b_matches[j] and b[j] == ca:
                a_matches[i] = True
                b_matches[j] = True
                matches += 1
                break
    if matches == 0:
        return 0.0
    transpositions = 0
    k = 0
    for i in range(la):
        if a_matches[i]:
            while not b_matches[k]:
                k += 1
            if a[i] != b[k]:
                transpositions += 1
            k += 1
    return (
        matches / la + matches / lb + (matches - transpositions / 2) / matches
    ) / 3


def _similar_long(name):
    # clap compares the candidate (without a particular number of leading
    # dashes in some cases) against every long flag and reports the best
    # candidate over its confidence threshold.
    best = None
    best_score = 0.0
    for opt in OPTIONS:
        cand = opt[1]
        score = _jaro(name, cand)
        if score > best_score:
            best_score = score
            best = opt
    if best is not None and best_score > 0.8:
        return best
    return None


class Cli:
    def __init__(self):
        self.flags = set()
        self.values = {}
        self.files = []
        self.present = set()  # option keys explicitly supplied


def _parse_usize(value, opt):
    """Parse as Rust's usize FromStr, raising a clap-style error."""

    label = f"--{opt[1]} {opt[4]}"
    if value == "":
        raise _clap_error(
            f"invalid value '' for '{label}': cannot parse integer from empty string"
        )
    digits = value[1:] if value.startswith("+") else value
    if not digits or any(c < "0" or c > "9" for c in digits):
        raise _clap_error(
            f"invalid value '{value}' for '{label}': invalid digit found in string"
        )
    number = int(digits, 10)
    if number > 2**64 - 1:
        raise _clap_error(
            f"invalid value '{value}' for '{label}': number too large to fit in target type"
        )
    return number


def _parse_u8_ranged(value, opt):
    """Parse as clap's ranged parser for a u8 (via i64)."""

    label = f"--{opt[1]} {opt[4]}"
    if value == "":
        raise _clap_error(
            f"invalid value '' for '{label}': cannot parse integer from empty string"
        )
    body = value[1:] if value[:1] in "+-" else value
    if not body or any(c < "0" or c > "9" for c in body):
        raise _clap_error(
            f"invalid value '{value}' for '{label}': invalid digit found in string"
        )
    number = int(value, 10)
    if number > 2**63 - 1 or number < -(2**63):
        raise _clap_error(
            f"invalid value '{value}' for '{label}': number too large to fit in target type"
        )
    if number < 0 or number > 255:
        raise _clap_error(
            f"invalid value '{value}' for '{label}': {number} is not in 0..=255"
        )
    return number


def _validate_value(opt, value):
    key = opt[0]
    if key == "wraplen":
        return _parse_usize(value, opt)
    if key == "tabsize":
        return _parse_u8_ranged(value, opt)
    if key == "completion":
        if value == "":
            raise _clap_error(
                "a value is required for '--completion <SHELL>' but none was supplied\n"
                "  [possible values: bash, elvish, fish, powershell, zsh]"
            )
        if value not in SHELLS:
            raise _clap_error(
                f"invalid value '{value}' for '--completion <SHELL>'\n"
                "  [possible values: bash, elvish, fish, powershell, zsh]"
            )
        return value
    if key == "config":
        if value == "":
            raise _clap_error(
                "a value is required for '--config <PATH>' but none was supplied"
            )
        return value
    return value


def _missing_value_error(opt):
    if opt[0] == "completion":
        return _clap_error(
            "a value is required for '--completion <SHELL>' but none was supplied\n"
            "  [possible values: bash, elvish, fish, powershell, zsh]"
        )
    return _clap_error(
        f"a value is required for '--{opt[1]} {opt[4]}' but none was supplied"
    )


def parse_cli(argv, prog):
    cli = Cli()
    i = 0
    only_files = False
    seen_positional = False

    def repeat_check(opt):
        if opt[0] in cli.present:
            label = f"--{opt[1]} {opt[4]}" if opt[3] else f"--{opt[1]}"
            raise _clap_error(
                f"the argument '{label}' cannot be used multiple times",
                usage=_usage_general(prog),
                prog=prog,
            )
        cli.present.add(opt[0])

    def unexpected(arg_display, similar_name=None, usage_opt=None):
        similar = _similar_long(similar_name) if similar_name else None
        if similar is not None:
            message = (
                f"unexpected argument '{arg_display}' found\n\n"
                f"  tip: a similar argument exists: '--{similar[1]}'"
            )
            usage = _usage_for_option(prog, similar)
        else:
            message = (
                f"unexpected argument '{arg_display}' found\n\n"
                f"  tip: to pass '{arg_display}' as a value, use '-- {arg_display}'"
            )
            if usage_opt is not None:
                usage = _usage_for_option(prog, usage_opt)
            elif seen_positional:
                usage = f"{prog} <files>..."
            else:
                usage = _usage_general(prog)
        raise _clap_error(message, usage=usage, prog=prog)

    def take_value(opt, attached):
        nonlocal i
        if attached is not None:
            return _validate_value(opt, attached)
        # A following token that looks like an option (other than a bare
        # "-") does not count as a value.
        if i + 1 >= len(argv):
            raise _missing_value_error(opt)
        nxt = argv[i + 1]
        if nxt == "--" or (len(nxt) > 1 and nxt.startswith("-") and nxt != "-"):
            # A small exception: clap still consumes a token that cannot be
            # an option because it is numeric-ish in some parsers; for this
            # program it reports the option as missing a value.
            raise _missing_value_error(opt)
        i += 1
        return _validate_value(opt, nxt)

    while i < len(argv):
        arg = argv[i]
        if only_files:
            cli.files.append(arg)
            seen_positional = True
            i += 1
            continue
        if arg == "--":
            only_files = True
            i += 1
            continue
        if arg.startswith("--"):
            body = arg[2:]
            if "=" in body:
                name, attached = body.split("=", 1)
                has_attached = True
            else:
                name, attached, has_attached = body, None, False
            if name == "":
                unexpected("--", similar_name=None)
            opt = _LONG.get(name)
            if opt is None:
                unexpected(arg, similar_name=name)
            if opt[0] in ("help", "version"):
                if has_attached:
                    raise _clap_error(
                        f"unexpected value '{attached}' for '--{name}' found; no more were expected",
                        usage=_usage_for_option(prog, opt),
                        prog=prog,
                    )
                if opt[0] == "help":
                    raise CliExit(0, stdout=help_text(prog))
                raise CliExit(0, stdout=f"tex-fmt {VERSION}\n")
            if not opt[3] and has_attached:
                raise _clap_error(
                    f"unexpected value '{attached}' for '--{name}' found; no more were expected",
                    usage=_usage_for_option(prog, opt),
                    prog=prog,
                )
            repeat_check(opt)
            if opt[3]:
                cli.values[opt[0]] = take_value(opt, attached if has_attached else None)
            else:
                cli.flags.add(opt[0])
            i += 1
            continue
        if arg.startswith("-") and arg != "-":
            # A cluster of short options.
            cluster = arg[1:]
            j = 0
            while j < len(cluster):
                ch = cluster[j]
                opt = _SHORT.get(ch)
                if opt is None:
                    unexpected(f"-{ch}", similar_name=None)
                if opt[0] == "help":
                    raise CliExit(0, stdout=help_text(prog))
                if opt[0] == "version":
                    raise CliExit(0, stdout=f"tex-fmt {VERSION}\n")
                repeat_check(opt)
                if opt[3]:
                    rest = cluster[j + 1 :]
                    if rest.startswith("="):
                        attached = rest[1:]
                    elif rest:
                        attached = rest
                    else:
                        attached = None
                    cli.values[opt[0]] = take_value(opt, attached)
                    j = len(cluster)
                else:
                    cli.flags.add(opt[0])
                    j += 1
            i += 1
            continue
        cli.files.append(arg)
        seen_positional = True
        i += 1
    return cli
