                b_matches[j] = True
                matches += 1
                break
    if matches == 0:
        return 0.0
    transpositions = 0
    k = 0
    for i in range(la):
        if a_matches[i]:
            while not b_matches[k]:
                k += 1
            if a[i] != b[k]:
                transpositions += 1
            k += 1
    return (
        matches / la + matches / lb + (matches - transpositions / 2) / matches
    ) / 3


def _similar_long(name):
    # clap compares the candidate (without a particular number of leading
    # dashes in some cases) against every long flag and reports the best
    # candidate over its confidence threshold.
    best = None
    best_score = 0.0
    for opt in OPTIONS:
        cand = opt[1]
        score = _jaro(name, cand)
        if score > best_score:
            best_score = score
            best = opt
    if best is not None and best_score > 0.8:
        return best
    return None


class Cli:
    def __init__(self):
        self.flags = set()
        self.values = {}
        self.files = []
        self.present = set()  # option keys explicitly supplied


def _parse_usize(value, opt):
    """Parse as Rust's usize FromStr, raising a clap-style error."""

    label = f"--{opt[1]} {opt[4]}"
    if value == "":
        raise _clap_error(
            f"invalid value '' for '{label}': cannot parse integer from empty string"
        )
    digits = value[1:] if value.startswith("+") else value
    if not digits or any(c < "0" or c > "9" for c in digits):
        raise _clap_error(
            f"invalid value '{value}' for '{label}': invalid digit found in string"
        )
    number = int(digits, 10)
    if number > 2**64 - 1:
        raise _clap_error(
            f"invalid value '{value}' for '{label}': number too large to fit in target type"
        )
    return number


def _parse_u8_ranged(value, opt):
    """Parse as clap's ranged parser for a u8 (via i64)."""

    label = f"--{opt[1]} {opt[4]}"
    if value == "":
        raise _clap_error(
            f"invalid value '' for '{label}': cannot parse integer from empty string"
        )
    body = value[1:] if value[:1] in "+-" else value
    if not body or any(c < "0" or c > "9" for c in body):
        raise _clap_error(
            f"invalid value '{value}' for '{label}': invalid digit found in string"
        )
    number = int(value, 10)
    if number > 2**63 - 1 or number < -(2**63):
        raise _clap_error(
            f"invalid value '{value}' for '{label}': number too large to fit in target type"
        )
    if number < 0 or number > 255:
        raise _clap_error(
            f"invalid value '{value}' for '{label}': {number} is not in 0..=255"
        )
    return number


def _validate_value(opt, value):
    key = opt[0]
    if key == "wraplen":
        return _parse_usize(value, opt)
    if key == "tabsize":
        return _parse_u8_ranged(value, opt)
    if key == "completion":
        if value == "":
            raise _clap_error(
                "a value is required for '--completion <SHELL>' but none was supplied\n"
                "  [possible values: bash, elvish, fish, powershell, zsh]"
            )
        if value not in SHELLS:
            raise _clap_error(
                f"invalid value '{value}' for '--completion <SHELL>'\n"
                "  [possible values: bash, elvish, fish, powershell, zsh]"
            )
        return value
    if key == "config":
        if value == "":
            raise _clap_error(
                "a value is required for '--config <PATH>' but none was supplied"
            )
        return value
    return value


def _missing_value_error(opt):
    if opt[0] == "completion":
        return _clap_error(
            "a value is required for '--completion <SHELL>' but none was supplied\n"
            "  [possible values: bash, elvish, fish, powershell, zsh]"
        )
    return _clap_error(
        f"a value is required for '--{opt[1]} {opt[4]}' but none was supplied"
    )


def parse_cli(argv, prog):
    cli = Cli()
    i = 0
    only_files = False
    seen_positional = False

    def repeat_check(opt):
        if opt[0] in cli.present:
            label = f"--{opt[1]} {opt[4]}" if opt[3] else f"--{opt[1]}"
            raise _clap_error(
                f"the argument '{label}' cannot be used multiple times",
                usage=_usage_general(prog),
                prog=prog,
            )
        cli.present.add(opt[0])

    def unexpected(arg_display, similar_name=None, usage_opt=None):
        similar = _similar_long(similar_name) if similar_name else None
        if similar is not None:
            message = (
                f"unexpected argument '{arg_display}' found\n\n"
                f"  tip: a similar argument exists: '--{similar[1]}'"
            )
            usage = _usage_for_option(prog, similar)
        else:
            message = (
                f"unexpected argument '{arg_display}' found\n\n"
                f"  tip: to pass '{arg_display}' as a value, use '-- {arg_display}'"
            )
            if usage_opt is not None:
                usage = _usage_for_option(prog, usage_opt)
            elif seen_positional:
                usage = f"{prog} <files>..."
            else:
                usage = _usage_general(prog)
        raise _clap_error(message, usage=usage, prog=prog)

    def take_value(opt, attached):
        nonlocal i
        if attached is not None:
            return _validate_value(opt, attached)
        # A following token that looks like an option (other than a bare
        # "-") does not count as a value.
        if i + 1 >= len(argv):
            raise _missing_value_error(opt)
        nxt = argv[i + 1]
        if nxt == "--" or (len(nxt) > 1 and nxt.startswith("-") and nxt != "-"):
            # A small exception: clap still consumes a token that cannot be
            # an option because it is numeric-ish in some parsers; for this
            # program it reports the option as missing a value.
            raise _missing_value_error(opt)
        i += 1
        return _validate_value(opt, nxt)

    while i < len(argv):
        arg = argv[i]
        if only_files:
            cli.files.append(arg)
            seen_positional = True
            i += 1
            continue
        if arg == "--":
            only_files = True
            i += 1
            continue
        if arg.startswith("--"):
            body = arg[2:]
            if "=" in body:
                name, attached = body.split("=", 1)
                has_attached = True
            else:
                name, attached, has_attached = body, None, False
            if name == "":
                unexpected("--", similar_name=None)
            opt = _LONG.get(name)
            if opt is None:
                unexpected(arg, similar_name=name)
            if opt[0] in ("help", "version"):
                if has_attached:
                    raise _clap_error(
                        f"unexpected value '{attached}' for '--{name}' found; no more were expected",
                        usage=_usage_for_option(prog, opt),
                        prog=prog,
                    )
                if opt[0] == "help":
                    raise CliExit(0, stdout=help_text(prog))
                raise CliExit(0, stdout=f"tex-fmt {VERSION}\n")
            if not opt[3] and has_attached:
                raise _clap_error(
                    f"unexpected value '{attached}' for '--{name}' found; no more were expected",
                    usage=_usage_for_option(prog, opt),
                    prog=prog,
                )
            repeat_check(opt)
            if opt[3]:
                cli.values[opt[0]] = take_value(opt, attached if has_attached else None)
            else:
                cli.flags.add(opt[0])
            i += 1
            continue
        if arg.startswith("-") and arg != "-":
            # A cluster of short options.
            cluster = arg[1:]
            j = 0
            while j < len(cluster):
                ch = cluster[j]
                opt = _SHORT.get(ch)
                if opt is None:
                    unexpected(f"-{ch}", similar_name=None)
                if opt[0] == "help":
                    raise CliExit(0, stdout=help_text(prog))
                if opt[0] == "version":
                    raise CliExit(0, stdout=f"tex-fmt {VERSION}\n")
                repeat_check(opt)
                if opt[3]:
                    rest = cluster[j + 1 :]
                    if rest.startswith("="):
                        attached = rest[1:]
                    elif rest:
                        attached = rest
                    else:
                        attached = None
                    cli.values[opt[0]] = take_value(opt, attached)
                    j = len(cluster)
                else:
                    cli.flags.add(opt[0])
                    j += 1
            i += 1
            continue
        cli.files.append(arg)
        seen_positional = True
        i += 1
    return cli
