                parts = []
                cur = []
                quote = None
                esc = False
                for ch in inner:
                    if esc:
                        cur.append(ch)
                        esc = False
                    elif ch == "\\" and quote == '"':
                        cur.append(ch)
                        esc = True
                    elif quote:
                        cur.append(ch)
                        if ch == quote:
                            quote = None
                    elif ch in "\"'":
                        quote = ch
                        cur.append(ch)
                    elif ch == ",":
                        parts.append("".join(cur))
                        cur = []
                    else:
                        cur.append(ch)
                if cur or inner.rstrip().endswith(","):
                    parts.append("".join(cur))
                for part in parts:
                    part = part.strip()
                    if not part:
                        continue
                    if part[:1] in "\"'":
                        items.append(_toml_unquote(part, path_display))
                    elif part in ("true", "false"):
                        items.append(part == "true")
                    else:
                        try:
                            items.append(int(part, 10))
                        except ValueError:
                            try:
                                items.append(float(part))
                            except ValueError:
                                fail()
            parsed = items
        elif value[:1] in "\"'":
            parsed = _toml_unquote(value, path_display)
        else:
            try:
                parsed = int(value.replace("_", ""), 10)
            except ValueError:
                try:
                    parsed = float(value)
                except ValueError:
                    fail()
        section[key] = parsed
