def _load_toml(text, path_display):
    """Parse TOML, preferring a real parser when one is available."""

    try:
        try:
            import tomllib  # Python 3.11+
        except ModuleNotFoundError:  # pragma: no cover
            import tomli as tomllib  # type: ignore
    except ModuleNotFoundError:
        return _load_toml_fallback(text, path_display)
    try:
        return tomllib.loads(text)
    except Exception:
        raise RustPanic(
            "src/config.rs:119:9",
            f"Failed to read config file at {path_display}",
        )


def _toml_unquote(token, path_display):
    token = token.strip()
    if len(token) >= 2 and token[0] == token[-1] and token[0] in "\"'":
        body = token[1:-1]
        if token[0] == "'":
            return body
        # Enough TOML basic-string escapes for configuration files.
        out = []
        i = 0
        escapes = {"n": "\n", "t": "\t", "r": "\r", '"': '"', "\\": "\\", "b": "\b", "f": "\f"}
        while i < len(body):
            if body[i] == "\\" and i + 1 < len(body):
                nxt = body[i + 1]
                if nxt == "u" and i + 5 < len(body) + 1:
                    try:
                        out.append(chr(int(body[i + 2 : i + 6], 16)))
                        i += 6
                        continue
                    except Exception:
                        pass
                out.append(escapes.get(nxt, nxt))
                i += 2
            else:
                out.append(body[i])
                i += 1
        return "".join(out)
    return token


def _load_toml_fallback(text, path_display):
    """A deliberately small TOML reader for tex-fmt configuration files.

    It understands the flat key/value pairs, comments, strings, numbers,
    booleans and (possibly multi-line) arrays used by this program.
    Anything it cannot make sense of is reported in the same way as a
    TOML syntax error in the reference program.
    """

    def fail():
        raise RustPanic(
            "src/config.rs:119:9",
            f"Failed to read config file at {path_display}",
        )

    result = {}
    # Remove comments that are outside strings, character by character.
    lines = []
    for raw_line in text.splitlines():
        out = []
        quote = None
        esc = False
        for ch in raw_line:
            if esc:
                out.append(ch)
                esc = False
            elif ch == "\\" and quote == '"':
                out.append(ch)
                esc = True
            elif quote:
                out.append(ch)
                if ch == quote:
                    quote = None
            elif ch in "\"'":
                quote = ch
                out.append(ch)
            elif ch == "#":
                break
            else:
                out.append(ch)
        lines.append("".join(out))

    # Join multi-line arrays.
    joined = []
    buf = ""
    depth = 0
    for line in lines:
        buf = f"{buf} {line}".strip() if buf else line
        depth += line.count("[") - line.count("]")
        if depth <= 0:
            joined.append(buf)
            buf = ""
            depth = 0
    if buf:
        fail()

    section = result
    for line in joined:
        line = line.strip()
        if not line:
            continue
        if line.startswith("[") and line.endswith("]") and "=" not in line:
            # Tables are irrelevant to tex-fmt's flat options, but keep
            # parsing subsequent keys into a nested table.
            name = _toml_unquote(line[1:-1].strip(), path_display)
            section = {}
            result[name] = section
            continue
        if "=" not in line:
            fail()
        key, value = line.split("=", 1)
        key = _toml_unquote(key.strip(), path_display)
        value = value.strip()
        if not value or key in section:
            fail()
        if value == "true":
            parsed = True
        elif value == "false":
            parsed = False
        elif value.startswith("[") and value.endswith("]"):
            inner = value[1:-1].strip()
            items = []
            if inner:
                # Split on commas outside strings.
                parts = []
                cur = []
                quote = None
                esc = False
                for ch in inner:
                    if esc:
                        cur.append(ch)
                        esc = False
                    elif ch == "\\" and quote == '"':
                        cur.append(ch)
                        esc = True
                    elif quote:
                        cur.append(ch)
                        if ch == quote:
                            quote = None
                    elif ch in "\"'":
                        quote = ch
                        cur.append(ch)
                    elif ch == ",":
                        parts.append("".join(cur))
                        cur = []
                    else:
                        cur.append(ch)
                if cur or inner.rstrip().endswith(","):
                    parts.append("".join(cur))
                for part in parts:
                    part = part.strip()
                    if not part:
                        continue
                    if part[:1] in "\"'":
                        items.append(_toml_unquote(part, path_display))
                    elif part in ("true", "false"):
                        items.append(part == "true")
                    else:
                        try:
                            items.append(int(part, 10))
                        except ValueError:
                            try:
                                items.append(float(part))
                            except ValueError:
                                fail()
            parsed = items
        elif value[:1] in "\"'":
            parsed = _toml_unquote(value, path_display)
        else:
            try:
                parsed = int(value.replace("_", ""), 10)
            except ValueError:
                try:
                    parsed = float(value)
                except ValueError:
                    fail()
        section[key] = parsed
    return result


def _read_config_file(path, display):
    try:
        with open(path, "rb") as fh:
            data = fh.read()
    except OSError as err:
        raise RustPanic(
            "src/config.rs:83:63",
            "called `Result::unwrap()` on an `Err` value: "
            f'Os {{ code: {err.errno or 1}, kind: {_os_error_kind(err)}, '
            f'message: "{err.strerror or str(err)}" }}',
        )
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        # Rust's read_to_string reports invalid UTF-8 as an io error.
        raise RustPanic(
            "src/config.rs:83:63",
            "called `Result::unwrap()` on an `Err` value: "
            'Custom { kind: InvalidData, error: "stream did not contain valid UTF-8" }',
        )
