    except Exception:
        return False


def _config_dir_user():
    xdg = os.environ.get("XDG_CONFIG_HOME")
    if xdg and os.path.isabs(xdg):
        return xdg
    home = os.environ.get("HOME")
    if home:
        return os.path.join(home, ".config")
    return None


def find_config_path(cli):
    """Return (path_to_read_or_None, display_value_or_None)."""

    if "config" in cli.values:
        display = cli.values["config"]
        if "noconfig" in cli.flags:
            return None, display
        return display, display
    if "noconfig" in cli.flags:
        return None, None

    cwd = os.getcwd()
    candidate = os.path.join(cwd, "tex-fmt.toml")
    if os.path.exists(candidate):
        return candidate, candidate

    # The root of the enclosing git repository: the closest ancestor
    # (including the current directory) containing a .git directory.
    ancestor = cwd
    while True:
        if _is_dir(os.path.join(ancestor, ".git")):
            candidate = os.path.join(ancestor, "tex-fmt.toml")
            if os.path.exists(candidate):
                return candidate, candidate
            break
        parent = os.path.dirname(ancestor)
        if parent == ancestor:
            break
        ancestor = parent

    config_home = _config_dir_user()
    if config_home:
        candidate = os.path.join(config_home, "tex-fmt", "tex-fmt.toml")
        if os.path.exists(candidate):
            return candidate, candidate
    return None, None


