def rust_path_extension(path):
    """Rust Path::extension for ordinary Unix paths.

    Returns None for no extension, otherwise the extension (possibly "").
    """

    trimmed = path.rstrip("/")
    if trimmed in ("", ".", ".."):
        return None
    name = trimmed.rsplit("/", 1)[-1]
    if name in ("", ".", ".."):
        return None
    if name.startswith(".") and name.count(".") == 1:
        return None
    if "." not in name:
        return None
    return name.rsplit(".", 1)[1]


def rust_set_tex_extension(path):
    trimmed = path.rstrip("/")
    name = trimmed.rsplit("/", 1)[-1] if trimmed else ""
    if name in ("", ".", ".."):
        return path
    if rust_path_extension(path) is not None:
        return path
    return trimmed + ".tex"


def _path_dedup_key(path):
    # Rust Path equality compares components, which collapses repeated
    # separators and interior "." components.
    absolute = path.startswith("/")
    parts = []
    for part in path.split("/"):
        if part in ("", "."):
            # A leading "./" is a distinct CurDir component in Rust.
            if part == "." and not parts and not absolute:
                parts.append(".")
            continue
        parts.append(part)
    return (absolute, tuple(parts))


def transform_input_paths(raw_files):
    out = []
    for path in raw_files:
        if _is_dir(path):
            transformed = path
        elif rust_path_extension(path) is None:
            transformed = rust_set_tex_extension(path)
        else:
            transformed = path
        out.append(transformed)
    # Rust Vec::dedup removes only consecutive duplicates.
    deduped = []
    for path in out:
        if deduped and _path_dedup_key(deduped[-1]) == _path_dedup_key(path):
            continue
        deduped.append(path)
    return deduped


