class _IgnorePattern:
    __slots__ = ("base", "negation", "dir_only", "anchored", "pattern", "segments")

    def __init__(self, base, line):
        self.base = base  # absolute directory containing the ignore file
        self.negation = False
        self.dir_only = False
        pattern = line
        # Trailing spaces are ignored unless backslash-escaped.
        while pattern.endswith(" ") and not pattern.endswith("\\ "):
            pattern = pattern[:-1]
        pattern = pattern.replace("\\ ", " ")
        if pattern.startswith("!"):
            self.negation = True
            pattern = pattern[1:]
        elif pattern.startswith("\\!"):
            pattern = pattern[1:]
        if pattern.startswith("\\#"):
            pattern = pattern[1:]
        if pattern.endswith("/"):
            self.dir_only = True
            pattern = pattern[:-1]
        self.anchored = "/" in pattern
        if pattern.startswith("/"):
            pattern = pattern[1:]
            self.anchored = True
        self.pattern = pattern
        self.segments = pattern.split("/") if pattern else []

    def _segment_match(self, pat, text):
        # Convert one path-segment glob (no "/") to a regex.
        out = []
        i = 0
        while i < len(pat):
            ch = pat[i]
            if ch == "*":
                out.append("[^/]*")
            elif ch == "?":
                out.append("[^/]")
            elif ch == "[":
                j = i + 1
                if j < len(pat) and pat[j] in "!^":
                    j += 1
                if j < len(pat) and pat[j] == "]":
                    j += 1
                while j < len(pat) and pat[j] != "]":
                    j += 1
                if j >= len(pat):
                    out.append(re.escape(ch))
                else:
                    inner = pat[i + 1 : j]
                    if inner.startswith("!"):
                        inner = "^" + inner[1:]
                    out.append("[" + inner.replace("\\", "\\\\") + "]")
                    i = j
            elif ch == "\\" and i + 1 < len(pat):
                i += 1
                out.append(re.escape(pat[i]))
            else:
                out.append(re.escape(ch))
            i += 1
        return re.fullmatch("".join(out), text) is not None

    def _match_segments(self, pats, parts):
        if not pats:
            return not parts
        if pats[0] == "**":
            # Zero or more whole segments.
            for skip in range(len(parts) + 1):
                if self._match_segments(pats[1:], parts[skip:]):
                    return True
            return False
        if not parts:
            return False
        if not self._segment_match(pats[0], parts[0]):
            return False
        return self._match_segments(pats[1:], parts[1:])

    def matches(self, abspath, is_dir):
        if self.dir_only and not is_dir:
            return False
        if not self.pattern:
            return False
        try:
            rel = os.path.relpath(abspath, self.base)
        except Exception:
            return False
        if rel.startswith(".." + os.sep) or rel == "..":
            return False
        parts = [] if rel == "." else rel.split(os.sep)
        if not parts:
            return False
        if self.anchored:
            return self._match_segments(self.segments, parts)
        # Unanchored: match the final component, or a trailing sequence
        # of components for patterns containing "**".
        if len(self.segments) == 1:
            return self._segment_match(self.segments[0], parts[-1])
        for start in range(len(parts)):
            if self._match_segments(self.segments, parts[start:]):
                return True
        return False


class _IgnoreRules:
    """A stack of pattern lists, lowest precedence first."""

    def __init__(self):
        self.groups = []  # list of lists of _IgnorePattern

    def add_file(self, path, base):
        try:
            with open(path, "r", encoding="utf-8", errors="surrogateescape") as fh:
                lines = fh.read().splitlines()
        except OSError:
            return
        group = []
        for line in lines:
            if not line.strip() or line.lstrip().startswith("#"):
                continue
            group.append(_IgnorePattern(base, line))
        if group:
            self.groups.append(group)

    def is_ignored(self, abspath, is_dir):
        ignored = False
        for group in self.groups:
            for pat in group:
                if pat.matches(abspath, is_dir):
                    ignored = not pat.negation
        return ignored

    def copy(self):
        other = _IgnoreRules()
        other.groups = list(self.groups)
        return other


def _global_gitignore_path():
    config_home = _config_dir_user()
    if config_home:
        return os.path.join(config_home, "git", "ignore")
    return None


def _add_dir_ignore_rules(rules, directory, in_git, git_root):
    """Add low-to-high precedence rules for one directory."""

    if in_git and git_root == directory:
        exclude = os.path.join(directory, ".git", "info", "exclude")
        if _is_file(exclude):
            rules.add_file(exclude, directory)
        global_ignore = _global_gitignore_path()
        # The global file has lower precedence than repo files; in the
        # reference's precedence it sits below .git/info/exclude.  It is
        # unusual, so approximation ordering with exclude is acceptable.
        if global_ignore and _is_file(global_ignore):
            rules.add_file(global_ignore, directory)
    if in_git:
        gitignore = os.path.join(directory, ".gitignore")
        if _is_file(gitignore):
            rules.add_file(gitignore, directory)
    ignore = os.path.join(directory, ".ignore")
    if _is_file(ignore):
        rules.add_file(ignore, directory)


def _initial_ignore_rules(root_abs):
    """Rules from ancestors of (and including) a walk root."""

    rules = _IgnoreRules()
