class _IgnorePattern:
    __slots__ = ("base", "negation", "dir_only", "anchored", "pattern", "segments")

    def __init__(self, base, line):
        self.base = base  # absolute directory containing the ignore file
        self.negation = False
        self.dir_only = False
        pattern = line
        # Trailing spaces are ignored unless backslash-escaped.
        while pattern.endswith(" ") and not pattern.endswith("\\ "):
            pattern = pattern[:-1]
        pattern = pattern.replace("\\ ", " ")
        if pattern.startswith("!"):
            self.negation = True
            pattern = pattern[1:]
        elif pattern.startswith("\\!"):
            pattern = pattern[1:]
        if pattern.startswith("\\#"):
            pattern = pattern[1:]
        if pattern.endswith("/"):
            self.dir_only = True
            pattern = pattern[:-1]
        self.anchored = "/" in pattern
        if pattern.startswith("/"):
            pattern = pattern[1:]
            self.anchored = True
        self.pattern = pattern
        self.segments = pattern.split("/") if pattern else []

    def _segment_match(self, pat, text):
        # Convert one path-segment glob (no "/") to a regex.
        out = []
        i = 0
        while i < len(pat):
            ch = pat[i]
            if ch == "*":
                out.append("[^/]*")
            elif ch == "?":
                out.append("[^/]")
            elif ch == "[":
                j = i + 1
                if j < len(pat) and pat[j] in "!^":
                    j += 1
                if j < len(pat) and pat[j] == "]":
                    j += 1
                while j < len(pat) and pat[j] != "]":
                    j += 1
                if j >= len(pat):
                    out.append(re.escape(ch))
                else:
                    inner = pat[i + 1 : j]
                    if inner.startswith("!"):
                        inner = "^" + inner[1:]
                    out.append("[" + inner.replace("\\", "\\\\") + "]")
                    i = j
            elif ch == "\\" and i + 1 < len(pat):
                i += 1
                out.append(re.escape(pat[i]))
            else:
                out.append(re.escape(ch))
            i += 1
        return re.fullmatch("".join(out), text) is not None

    def _match_segments(self, pats, parts):
        if not pats:
            return not parts
        if pats[0] == "**":
            # Zero or more whole segments.
            for skip in range(len(parts) + 1):
                if self._match_segments(pats[1:], parts[skip:]):
                    return True
            return False
        if not parts:
            return False
        if not self._segment_match(pats[0], parts[0]):
            return False
        return self._match_segments(pats[1:], parts[1:])

    def matches(self, abspath, is_dir):
        if self.dir_only and not is_dir:
            return False
        if not self.pattern:
            return False
        try:
            rel = os.path.relpath(abspath, self.base)
        except Exception:
            return False
        if rel.startswith(".." + os.sep) or rel == "..":
            return False
        parts = [] if rel == "." else rel.split(os.sep)
        if not parts:
            return False
        if self.anchored:
            return self._match_segments(self.segments, parts)
        # Unanchored: match the final component, or a trailing sequence
        # of components for patterns containing "**".
        if len(self.segments) == 1:
            return self._segment_match(self.segments[0], parts[-1])
        for start in range(len(parts)):
            if self._match_segments(self.segments, parts[start:]):
                return True
        return False


class _IgnoreRules:
    """A stack of pattern lists, lowest precedence first."""

    def __init__(self):
        self.groups = []  # list of lists of _IgnorePattern

    def add_file(self, path, base):
        try:
            with open(path, "r", encoding="utf-8", errors="surrogateescape") as fh:
                lines = fh.read().splitlines()
        except OSError:
            return
        group = []
        for line in lines:
            if not line.strip() or line.lstrip().startswith("#"):
                continue
            group.append(_IgnorePattern(base, line))
        if group:
            self.groups.append(group)

    def is_ignored(self, abspath, is_dir):
        ignored = False
        for group in self.groups:
            for pat in group:
                if pat.matches(abspath, is_dir):
                    ignored = not pat.negation
        return ignored

    def copy(self):
        other = _IgnoreRules()
        other.groups = list(self.groups)
        return other


def _global_gitignore_path():
    config_home = _config_dir_user()
    if config_home:
        return os.path.join(config_home, "git", "ignore")
    return None


def _add_dir_ignore_rules(rules, directory, in_git, git_root):
    """Add low-to-high precedence rules for one directory."""

    if in_git and git_root == directory:
        exclude = os.path.join(directory, ".git", "info", "exclude")
        if _is_file(exclude):
            rules.add_file(exclude, directory)
        global_ignore = _global_gitignore_path()
        # The global file has lower precedence than repo files; in the
        # reference's precedence it sits below .git/info/exclude.  It is
        # unusual, so approximation ordering with exclude is acceptable.
        if global_ignore and _is_file(global_ignore):
            rules.add_file(global_ignore, directory)
    if in_git:
        gitignore = os.path.join(directory, ".gitignore")
        if _is_file(gitignore):
            rules.add_file(gitignore, directory)
    ignore = os.path.join(directory, ".ignore")
    if _is_file(ignore):
        rules.add_file(ignore, directory)


def _initial_ignore_rules(root_abs):
    """Rules from ancestors of (and including) a walk root."""

    rules = _IgnoreRules()
    # Build the ancestor chain, outermost first.
    chain = []
    current = root_abs
    while True:
        chain.append(current)
        parent = os.path.dirname(current)
        if parent == current:
            break
        current = parent
    chain.reverse()
    git_root = None
    for directory in chain:
        if os.path.exists(os.path.join(directory, ".git")):
            git_root = directory
        _add_dir_ignore_rules(rules, directory, git_root is not None, git_root)
    return rules, git_root


SUPPORTED_EXTENSIONS = {"tex", "bib", "cls", "sty"}


def _walk_directory(display_root, rules, git_root, logger):
    """Depth-first, in readdir order, yielding supported file paths."""

    results = []
    root_abs = os.path.abspath(display_root)

    def recurse(display_dir, abs_dir, dir_rules, dir_git_root):
        try:
            entries = list(os.scandir(abs_dir))
        except OSError:
            return
        for entry in entries:
            name = entry.name
            display_path = display_dir.rstrip("/") + "/" + name if display_dir else name
            # When the root is given as "./", display_dir carries that
            # prefix through; the initial call sets it up.
            try:
                is_symlink = entry.is_symlink()
                is_dir_entry = entry.is_dir(follow_symlinks=False)
                is_file_entry = entry.is_file(follow_symlinks=False)
            except OSError:
                continue
            abs_path = os.path.join(abs_dir, name)
            if name.startswith("."):
                if logger is not None:
                    logger.debug_from_walker()
                continue
            if dir_rules.is_ignored(abs_path, is_dir_entry):
                if logger is not None:
                    logger.debug_from_walker()
                continue
            if is_dir_entry and not is_symlink:
                child_rules = dir_rules.copy()
                child_git_root = dir_git_root
                if os.path.exists(os.path.join(abs_path, ".git")):
                    child_git_root = abs_path
                _add_dir_ignore_rules(
                    child_rules, abs_path, child_git_root is not None, child_git_root
                )
                recurse(display_path, abs_path, child_rules, child_git_root)
            elif is_file_entry and not is_symlink:
                ext = rust_path_extension(name)
                if ext in SUPPORTED_EXTENSIONS:
                    results.append(display_path)
            # Symlinks and other special files are yielded by the walker
            # in the reference but are not regular files, so tex-fmt
            # does not format them in a directory search.

    # Preserve the caller's textual root prefix in result paths.  The
    # reference joins entry names onto the root as supplied ("./x",
    # "sub/x", "/abs/x"); a root of "." therefore yields "./x".
    display_prefix = display_root
    if display_prefix in (".", "./"):
        display_prefix = "."
    recurse(display_prefix, root_abs, rules, git_root)
    return results


def expand_recursive(paths, logger):
    results = []
    for path in paths:
        if _is_file(path):
            results.append(path)
        elif _is_dir(path):
            root_abs = os.path.abspath(path)
            rules, git_root = _initial_ignore_rules(root_abs)
            results.extend(_walk_directory(path, rules, git_root, logger))
        # Missing and special paths contribute no files in recursive mode.
    return results
