# ---------------------------------------------------------------------------
# The formatter itself
# ---------------------------------------------------------------------------

SPLIT_LITERALS = [
    "\\begin{",
    "\\end{",
    "\\part{",
    "\\part*{",
    "\\chapter{",
    "\\chapter*{",
    "\\section{",
    "\\section*{",
    "\\subsection{",
    "\\subsection*{",
    "\\subsubsection{",
    "\\subsubsection*{",
]


class Line:
    __slots__ = ("text", "number", "actual", "visual", "ignore", "decided")

    def __init__(self, text, number):
        self.text = text
        self.number = number
        self.actual = 0
        self.visual = 0
        self.ignore = False
        self.decided = False


def rust_lines(text):
    if text == "":
        return []
    parts = text.split("\n")
    if text.endswith("\n"):
        parts = parts[:-1]
        return [part[:-1] if part.endswith("\r") else part for part in parts]
    out = []
    for idx, part in enumerate(parts):
        if idx < len(parts) - 1 and part.endswith("\r"):
            part = part[:-1]
        out.append(part)
    return out


def find_comment_index(text):
    """Index of the first unescaped %, as a character index, or None."""

    for idx, ch in enumerate(text):
        if ch == "%" and (idx == 0 or text[idx - 1] != "\\"):
            return idx
    return None


def code_part(text):
    idx = find_comment_index(text)
    return text if idx is None else text[:idx]


def verbatim_diff(text, verbatims):
    for name in verbatims:
        if f"\\begin{{{name}}}" in text:
            return 1
    for name in verbatims:
        if f"\\end{{{name}}}" in text:
            return -1
    return 0


def find_split_index(code):
    """Earliest split-pattern index greater than zero, or None."""

    best = None
    for pat in SPLIT_LITERALS:
        idx = code.find(pat, 1)
        if idx != -1 and (best is None or idx < best):
            best = idx
    start = 1
    while True:
        idx = code.find("\\item", start)
        if idx == -1:
            break
        after = idx + len("\\item")
        if after >= len(code) or not ("a" <= code[after] <= "z" or "A" <= code[after] <= "Z"):
            if best is None or idx < best:
                best = idx
            break
        start = idx + 1
    return best


def _env_magnitude(code, begin, args):
    prefix = "\\begin{" if begin else "\\end{"
    for name in args.no_indent_envs:
        if code.startswith(f"{prefix}{name}}}"):
            return 0
    for name in args.lists:
        if code.startswith(f"{prefix}{name}}}"):
            return 2
    return 1


def calculate_indent(text, actual_before, args):
    code = code_part(text)
    balance = 0
    min_prefix = 0
    for ch in code:
        if ch in "{[(":
            balance += 1
        elif ch in "}])":
            balance -= 1
        if balance < min_prefix:
            min_prefix = balance

    env_diff = 0
    special = 0
    if code.startswith("\\begin{"):
        env_diff = _env_magnitude(code, True, args)
    elif code.startswith("\\end{"):
        magnitude = _env_magnitude(code, False, args)
        env_diff = -magnitude
        special = magnitude
    elif code.startswith("\\item"):
        after = len("\\item")
        if after >= len(code) or not (
            "a" <= code[after] <= "z" or "A" <= code[after] <= "Z"
        ):
            special = 1

    visual = actual_before + min_prefix
    if special and actual_before != 0:
        visual -= special
    actual = actual_before + balance + env_diff
    return actual, visual


def find_wrap_point(text, visual, args, target, line_index, line_number, logger):
    """Return the character index of the chosen wrap character, or None."""

    indent_chars = max(visual, 0) * args.tabsize
    wrap_chars = set(args.wrap_chars)
    total_chars = len(text)
    wrap_point = None  # (char index, byte index)
    byte_index = 0
    prev_char = None
    for char_index, ch in enumerate(text):
        counter = indent_chars + char_index
        if counter >= args.wrapmin and wrap_point is not None:
            break
        if (
            char_index > 0
            and char_index < total_chars - 1
            and ch in wrap_chars
            and prev_char != "\\"
        ):
            wrap_point = (char_index, byte_index)
        prev_char = ch
        byte_index += len(ch.encode("utf-8", "surrogateescape"))

    if wrap_point is None or wrap_point[1] > args.wraplen:
        logger.warn(
            target,
            f"Line {line_index} ({line_number}). Line cannot be wrapped.",
            line_log_extra(text),
        )
    if wrap_point is None:
        return None
    return wrap_point[0]


def format_text(source, target, args, logger):
    text = source
    if args.tabchar == "space":
        text = text.replace("\t", " " * args.tabsize)
    while "\n\n\n" in text:
        text = text.replace("\n\n\n", "\n\n")

    lines = [
        Line(trim_end_rust(raw), number)
        for number, raw in enumerate(rust_lines(text), start=1)
    ]

    actual_state = 0
    verbatim_count = 0
    ignore_block = False

    i = 0
    while i < len(lines):
        line = lines[i]

        if not line.decided:
            raw = line.text
            raw_trimmed_end = trim_end_rust(raw)
            is_off = raw_trimmed_end.endswith("% tex-fmt: off")
            is_on = raw_trimmed_end.endswith("% tex-fmt: on")
            is_skip = raw_trimmed_end.endswith("% tex-fmt: skip")
            ignore_block_before = ignore_block
            if is_off:
                if ignore_block:
                    logger.warn(
                        target,
                        f"Line {i + 1} ({line.number}). Cannot begin ignore block:",
                        line_log_extra(raw),
                    )
                else:
                    ignore_block = True
            elif is_on:
                if not ignore_block:
                    logger.warn(
                        target,
                        f"Line {i + 1} ({line.number}). No ignore block to end.",
                        line_log_extra(raw),
                    )
                else:
                    ignore_block = False
            verbatim_before = verbatim_count
            verbatim_count += verbatim_diff(raw, args.verbatims)
            verbatim_ignored = max(verbatim_before, verbatim_count) > 0
            line.ignore = bool(
                is_off or is_on or is_skip or ignore_block_before or verbatim_ignored
            )
            line.decided = True

        if verbatim_count < 0:
            logger.warn(
                target,
                f"Line {i + 1} ({line.number}). Verbatim count is negative.",
                line_log_extra(line.text),
            )

        if line.ignore:
            i += 1
            continue

        # From here on the line is processed with its leading whitespace
        # removed (the rendered indentation is supplied separately).
        line.text = trim_start_rust(line.text)

        code = code_part(line.text)
        split_index = find_split_index(code)
        if split_index is not None:
            logger.trace(
                target,
                f"Line {i + 1} ({line.number}). Placing environment on new line.",
                line_log_extra(line.text),
            )
            tail = Line(line.text[split_index:], line.number)
            line.text = line.text[:split_index]
            lines.insert(i + 1, tail)

        actual, visual = calculate_indent(line.text, actual_state, args)
        line.actual = actual
        line.visual = visual
        logger.trace(
            target,
            f"Line {i + 1} ({line.number}). Indent: actual = {actual}, visual = {visual}:",
            line_log_extra(line.text),
        )
        if actual < 0 or visual < 0:
            logger.warn(
                target,
                f"Line {i + 1} ({line.number}). Indent is negative.",
                line_log_extra(line.text),
            )

        wrapped = False
        if args.wrap:
            rendered_len = max(visual, 0) * args.tabsize + len(line.text)
            if rendered_len > args.wraplen:
