                last_non_indented = index + 1
        logger.warn(
            target,
            "Indent does not return to zero. "
            f"Last non-indented line is line {last_non_indented}",
        )
    first_negative = None
    for index, candidate in enumerate(lines):
        if not candidate.ignore and (candidate.actual < 0 or candidate.visual < 0):
            first_negative = index + 1
            break
    if first_negative is not None:
        logger.warn(
            target,
            "Negative indents. "
            f"First negatively indented line is line {first_negative}",
        )

    tab_char = "\t" if args.tabchar == "tab" else " "
    rendered = []
    for line in lines:
        if line.ignore:
            rendered.append(trim_end_rust(line.text))
        else:
            indent = tab_char * (max(line.visual, 0) * args.tabsize)
            rendered.append(trim_end_rust(indent + trim_start_rust(line.text)))
    return trim_end_rust("\n".join(rendered)) + "\n"
