# ---------------------------------------------------------------------------
# The formatter itself
# ---------------------------------------------------------------------------

SPLIT_LITERALS = [
    "\\begin{",
    "\\end{",
    "\\part{",
    "\\part*{",
    "\\chapter{",
    "\\chapter*{",
    "\\section{",
    "\\section*{",
    "\\subsection{",
    "\\subsection*{",
    "\\subsubsection{",
    "\\subsubsection*{",
]


class Line:
    __slots__ = ("text", "number", "actual", "visual", "ignore", "decided")

    def __init__(self, text, number):
        self.text = text
        self.number = number
        self.actual = 0
        self.visual = 0
        self.ignore = False
        self.decided = False


def rust_lines(text):
    if text == "":
        return []
    parts = text.split("\n")
    if text.endswith("\n"):
        parts = parts[:-1]
        return [part[:-1] if part.endswith("\r") else part for part in parts]
    out = []
    for idx, part in enumerate(parts):
        if idx < len(parts) - 1 and part.endswith("\r"):
            part = part[:-1]
        out.append(part)
    return out


def find_comment_index(text):
    """Index of the first unescaped %, as a character index, or None."""

    for idx, ch in enumerate(text):
        if ch == "%" and (idx == 0 or text[idx - 1] != "\\"):
            return idx
    return None


def code_part(text):
    idx = find_comment_index(text)
    return text if idx is None else text[:idx]


def verbatim_diff(text, verbatims):
    for name in verbatims:
        if f"\\begin{{{name}}}" in text:
            return 1
    for name in verbatims:
        if f"\\end{{{name}}}" in text:
            return -1
    return 0


def find_split_index(code):
    """Earliest split-pattern index greater than zero, or None."""

    best = None
    for pat in SPLIT_LITERALS:
        idx = code.find(pat, 1)
        if idx != -1 and (best is None or idx < best):
            best = idx
    start = 1
    while True:
        idx = code.find("\\item", start)
        if idx == -1:
            break
        after = idx + len("\\item")
        if after >= len(code) or not ("a" <= code[after] <= "z" or "A" <= code[after] <= "Z"):
            if best is None or idx < best:
                best = idx
            break
        start = idx + 1
    return best


def _env_magnitude(code, begin, args):
    prefix = "\\begin{" if begin else "\\end{"
    for name in args.no_indent_envs:
        if code.startswith(f"{prefix}{name}}}"):
            return 0
    for name in args.lists:
        if code.startswith(f"{prefix}{name}}}"):
            return 2
    return 1


def calculate_indent(text, actual_before, args):
    code = code_part(text)
    balance = 0
    min_prefix = 0
    for ch in code:
        if ch in "{[(":
            balance += 1
        elif ch in "}])":
            balance -= 1
        if balance < min_prefix:
            min_prefix = balance

    env_diff = 0
    special = 0
    if code.startswith("\\begin{"):
        env_diff = _env_magnitude(code, True, args)
    elif code.startswith("\\end{"):
        magnitude = _env_magnitude(code, False, args)
        env_diff = -magnitude
        special = magnitude
    elif code.startswith("\\item"):
        after = len("\\item")
        if after >= len(code) or not (
