# ---------------------------------------------------------------------------
# File and stdin processing, and main
# ---------------------------------------------------------------------------


def _rust_os_error(err):
    return (
        f'Os {{ code: {err.errno or 1}, kind: {_os_error_kind(err)}, '
        f'message: "{err.strerror or str(err)}" }}'
    )


def format_file(path, args, logger):
    """Format one file.  Return True on success."""

    try:
        with open(path, "rb") as fh:
            data = fh.read()
        source = data.decode("utf-8")
    except (OSError, UnicodeDecodeError):
        ext = rust_path_extension(path)
        if ext in SUPPORTED_EXTENSIONS:
            logger.error(path, "Could not open file.")
        else:
            logger.error(path, "File type invalid.")
        return False

    logger.info(path, "Formatting started.")
    formatted = format_text(source, path, args, logger)
    logger.info(path, "Formatting complete.")

    if args.print:
        write_stdout(formatted)
        return True
    if args.check:
        if formatted != source:
            logger.error(path, "Incorrect formatting.")
            return False
        return True
    if formatted != source:
        try:
            with open(path, "wb") as fh:
                fh.write(formatted.encode("utf-8", "surrogateescape"))
        except OSError as err:
            raise RustPanic(
                "src/write.rs:12:31",
                f"Could not write the file: {_rust_os_error(err)}",
            )
        return not args.fail_on_change
    return True


def process_stdin(args, logger):
    data = sys.stdin.buffer.read()
    try:
        source = data.decode("utf-8")
    except UnicodeDecodeError:
        logger.error(
            "<stdin>",
            "Could not read from stdin: stream did not contain valid UTF-8",
        )
        return 1
    logger.trace("<stdin>", f"Read {len(data)} bytes.")
    logger.info("<stdin>", "Formatting started.")
    formatted = format_text(source, "<stdin>", args, logger)
    logger.info("<stdin>", "Formatting complete.")
    write_stdout(formatted)
    return 0


def run(argv):
    prog = program_name()
    try:
        cli = parse_cli(argv, prog)
    except CliExit as exc:
        if exc.stdout:
            write_stdout(exc.stdout)
        if exc.stderr:
            try:
                sys.stderr.buffer.write(exc.stderr.encode("utf-8", "surrogateescape"))
                sys.stderr.buffer.flush()
            except Exception:
                pass
        return exc.status

    # Shell completions and the man page are generated before any
    # configuration file is read, completions taking precedence.
    if "completion" in cli.values:
        write_stdout(COMPLETIONS.get(cli.values["completion"], ""))
        return 0
    if "man" in cli.flags:
        write_stdout(MAN_PAGE)
        return 0

    args = build_args(cli)
    logger = args.logger

    if args.print_args:
        write_stdout(format_args(args))
        return 0

    if args.stdin:
        if cli.files or args.recursive:
            logger.error("", "Do not provide file name(s) when using --stdin.")
            return 1
        return process_stdin(args, logger)

    if not args.files:
        logger.error(
            "",
            "No files specified. Provide filenames, or pass --recursive or --stdin.",
        )
        return 1

    if not args.recursive and any(_is_dir(path) for path in args.files):
        logger.error("", "A directory was passed without --recursive.")
        return 1

    status = 0
    for path in args.files:
        if not format_file(path, args, logger):
            status = 1
    return status


def main():
    try:
        status = run(sys.argv[1:])
    except RustPanic as panic:
        panic.emit()
        return 101
    except BrokenPipeError:
        panic = RustPanic(
            "library/std/src/io/stdio.rs:1165:9",
            "failed printing to stdout: Broken pipe (os error 32)",
        )
        panic.emit()
        return 101
    return status


if __name__ == "__main__":
    sys.exit(main())
