def _use_color(stream):
    if "NO_COLOR" in os.environ:
        return False
    if os.environ.get("CLICOLOR_FORCE"):
        return True
    if os.environ.get("CLICOLOR") == "0":
        return False
    try:
        if not stream.isatty():
            return False
    except Exception:
        return False
    term = os.environ.get("TERM")
    if not term or term == "dumb":
        return False
    return True


def _bold(text):
    return f"\033[1m{text}\033[0m"


def _colorize_usage_line(line, prog):
    if not line.startswith("Usage:"):
        return line
    rest = line[len("Usage:") :]
    # Style the program name (first token) and any flag tokens.
    rest = rest.replace(prog, _bold(prog), 1)
    rest = re.sub(r"--[a-z][a-z-]*|(?<!\w)-[A-Za-z](?=[\s,\]]|$)", lambda m: _bold(m.group()), rest)
    return f"\033[1m\033[4mUsage:\033[0m{rest}"


def _colorize_help(text, prog):
    out = []
    for line in text.splitlines():
        if line.startswith("Usage:"):
            out.append(_colorize_usage_line(line, prog))
        elif line in ("Arguments:", "Options:"):
            out.append(f"\033[1m\033[4m{line}\033[0m")
        else:
            match = re.match(r"^(\s+)(.+?)(\s{2,})(\S.*)$", line)
            if match and match.group(2).startswith("-"):
                spec = re.sub(
                    r"--[a-z][a-z-]*|(?<!\w)-[A-Za-z](?=[\s,]|$)",
                    lambda m: _bold(m.group()),
                    match.group(2),
                )
                out.append(match.group(1) + spec + match.group(3) + match.group(4))
            else:
                out.append(line)
    return "\n".join(out) + "\n"


def _colorize_error(text, prog):
    lines = text.splitlines()
    out = []
    for line in lines:
        if line.startswith("error:"):
            line = "\033[1m\033[31merror:\033[0m" + line[len("error:") :]
            # Style quoted spans according to the message shape.
            def quoted_span(pattern, line, group_styles):
                m = re.search(pattern, line)
                if not m:
                    return line
                # Replace from the last group backwards so spans stay valid.
                for group, style in sorted(group_styles.items(), reverse=True):
                    a, b = m.span(group)
                    line = line[:a] + style(line[a:b]) + line[b:]
                return line

