import os,pty,subprocess,sys
# Create pty pairs and run with one stream pty, other pipe
def run(stdout_pty,stderr_pty,args=["--noconfig","missing.tex"]):
    masters=[]; slaves=[]
    def make():
        m,s=pty.openpty(); masters.append(m); return s
    out_slave=make() if stdout_pty else subprocess.PIPE
    err_slave=make() if stderr_pty else subprocess.PIPE
    env=dict(os.environ,TERM="xterm-256color")
