    if stderr_pty: os.close(err_slave)
    def readmaster(m):
        data=b""
        while True:
            try:
                chunk=os.read(m,4096)
            except OSError: break
            if not chunk: break
            data+=chunk
        return data
    outs={}
    # If both pty could deadlock on large but output small; read after wait with timeout rough
    p.wait(timeout=5)
    idx=0
    if stdout_pty: outs['out']=readmaster(masters[idx]); idx+=1
    else: outs['out']=p.stdout.read() if p.stdout else b''
    if stderr_pty: outs['err']=readmaster(masters[idx]); idx+=1
    else: outs['err']=p.stderr.read() if p.stderr else b''
    print("stdout_pty",stdout_pty,"stderr_pty",stderr_pty,args,"=>",outs)
